).CALCULATE(
    artist_name=name
)

result = county_public_safeties.WHERE(
    HAS(cities.WHERE(white > 90)) == 1
).CALCULATE(
    county_name=name,
    crime_rate=crime_rate
)

total_products_ordered = GRAPH.CALCULATE(
    total_quantity_before_date=SUM(
        Customer_Orders.WHERE(
            Customer_Orders.order_date < DATETIME('2018-03-17 07:13:53')
        ).Order_Items.order_quantity
    )
)

san_francisco_campus_fee_1996 = campuse.WHERE(
    campus == "San Francisco State University"
).csu_fee.WHERE(
    year == 1996
).SINGULAR().CALCULATE(
    campus_fee=campusfee
)

average_ages = GRAPH.CALCULATE(
    average_loser_age=AVG(
        IFF(
            (match.loser_age == "") | (match.loser_age == "N/A"),
            NULL,
            match.loser_age + 0.0
        )
    ),
    average_winner_age=AVG(
        IFF(
            (match.winner_age == "") | (match.winner_age == "N/A"),
            NULL,
            match.winner_age + 0.0
        )
    )
)

elimination_times = wrestler.eliminations.WHERE(
    wrestler.days_held > 50
).CALCULATE(
    time
)

result = GRAPH.CALCULATE(
    count_star=COUNT(highschoolers.WHERE((highschoolers.grade == 9) | (highschoolers.grade == 10)))
)

customer_type_counts = customer.PARTITION(
    name="customer_types",
    by=customer_type_code
).CALCULATE(
    customer_type_code=customer_type_code,
    customer_count=COUNT(customer)
)

result = customer_type_counts.TOP_K(1, by=customer_count.DESC()).SINGULAR().CALCULATE(
    num_customers_in_most_common_type=customer_count
)

num_project_members = GRAPH.CALCULATE(
    total_project_members=COUNT(
        project_staffs.WHERE(
            (role_code == 'leader') | (date_from < DATETIME('1989-04-24 23:51:54'))
        )
    )
